+
+// firstFailureOutputLine is the first nonblank line of the output of the check the first failure
+// names, trimmed and cut to 200 characters; "" when the first failure is an acceptance scenario,
+// not a failing check of the pass, or the check has no nonblank output.
+func firstFailureOutputLine(pass verify.Pass) string {
+	if len(missingAcceptanceItems(pass)) > 0 || len(pass.Failing) == 0 {
+		return ""
+	}
+	for _, r := range pass.Checks {
+		if r.Name != pass.Failing[0] || r.Status == 0 {
+			continue
+		}
+		for _, line := range strings.Split(r.Output, "\n") {
+			if line = strings.TrimSpace(line); line != "" {
+				if rs := []rune(line); len(rs) > 200 {
+					line = string(rs[:200])
+				}
+				return line
+			}
+		}
+		return ""
 	}
 	return ""
 }

+// firstFailureOutputNotice is the notice sentence that quotes firstFailureOutputLine, or "".
+func firstFailureOutputNotice(pass verify.Pass) string {
+	if q := firstFailureOutputLine(pass); q != "" {
+		return "First line of its output: " + q + "\n"
+	}
+	return ""
+}
